'use strict';
// Community-informed tools. All records remain in browser-local prototype state.
const communityGroups=[
['A gentler start',[['starter','A seven-day start','One category, a realistic exception, a small first step.'],['rule-check','Does this fit my rules?','Make replacements and essential exceptions explicit.'],['rule-result','Your exception reflection','Support a decision without pretending to approve it.'],['progress-review','Progress that stays','Keep check-ins and context after a purchase.']]],
['Life beyond shopping',[['joy-menu','Your no-spend menu','Personal alternatives matched to your energy.'],['add-activity','Add a little joy','A free activity using what you already have.'],['food-rescue','Before food delivery','Make an easy meal plan with your own food.'],['friction','Make shopping less automatic','A manual checklist for shopping triggers.']]],
['Enough, in practice',[['use-up','Use what is open','Finish safe, suitable items before replacing.'],['use-up-item','Your use-up progress','Track a remaining amount without pressure.'],['declutter','One item, less overwhelm','Keep, repair, give away or responsibly let go.']]],
['Spending with context',[['deal-check','A deal or a need?','Focus on the actual outflow, not the discount.'],['pockets','Your allowance pockets','Separate small budgets, with optional carry-over.'],['edit-pocket','A personal pocket','Give fun, gifts or a category a realistic boundary.'],['subscriptions','Recurring spending review','Manual subscription inventory and cancellation notes.'],['add-subscription','Add a recurring cost','Know what you use and what you pay for.'],['purchase-history','Purchase history','Planned, exception and unplanned records belong.'],['return-check','A return, if it fits','Track a policy date and confirm an actual refund.'],['commitments','Payment commitments','Keep manual obligations visible without debt advice.'],['add-commitment','Add a commitment','Your balance, payment and date, entered by you.']]]];
function migrateCommunity(data){const base={activities:[{id:1,name:'Tea and a chapter I already own',energy:'Low',minutes:10,done:0},{id:2,name:'A short walk with a friend',energy:'Medium',minutes:20,done:0},{id:3,name:'Finish a small craft project',energy:'Medium',minutes:30,done:0}],friction:{emails:false,cards:false,apps:false,bnpl:false},pockets:[{id:1,name:'Clothing',limit:70,carry:0,rollover:false,spent:45},{id:2,name:'Skincare',limit:30,carry:0,rollover:false,spent:0},{id:3,name:'Gifts',limit:20,carry:0,rollover:false,spent:0}],subscriptions:[{id:1,name:'Unused streaming plan',amount:12,used:false,status:'Active'},{id:2,name:'Music I enjoy',amount:8,used:true,status:'Active'}],commitments:[],checkins:{},pauseEvents:[],pantryPlan:{ingredients:'Rice, frozen vegetables, eggs',meal:'A simple meal I know how to make.',backup:'A quick option from my freezer.'},ruleDecisions:[],declutterLog:[],refundTotal:0};for(const [key,value]of Object.entries(base))if(data[key]===undefined)data[key]=structuredClone(value);if(!Object.keys(data.checkins).length){for(let day=1;day<=9;day++)data.checkins[`2026-10-${String(day).padStart(2,'0')}`]={mood:'Good',spending:[4,7].includes(day)?'Only planned purchases':'No purchases',note:'Sample check-in',sample:true};if(data.checked)data.checkins['2026-10-10']={mood:data.mood,spending:data.checkInSpending||'No purchases',note:data.checkInNote||'',sample:false};}for(const o of data.owned){if(o.remaining===undefined)o.remaining=o.category==='Skincare'?50:100;if(o.useStatus===undefined)o.useStatus='In use';}for(const w of data.wants){if(w.productUrl===undefined)w.productUrl='';if(w.reminderEnabled===undefined)w.reminderEnabled=true;if(!w.createdAt)w.createdAt=new Date().toISOString();if(!w.reviewIntervalHours)w.reviewIntervalHours=48;if(!w.cooldownUntil)w.cooldownUntil=new Date(Date.now()+Number(w.hours||0)*3600000).toISOString();}for(const p of data.purchases){if(!p.id)p.id=Date.parse(p.date)||Date.now();if(!p.refund)p.refund=0;}return data;}
let activityEnergy='All',selectedPocket=1,selectedSubscription=1,selectedPurchase=0,selectedCommitment=0,lastRecordId=Date.now();
const newRecordId=()=>++lastRecordId;
const pocket=()=>state.pockets.find(p=>p.id===selectedPocket)||state.pockets[0];
const purchase=()=>state.purchases.find(p=>p.id===selectedPurchase)||state.purchases.at(-1);
const pocketAvailable=p=>Math.max(0,p.limit+(p.rollover?p.carry:0)-p.spent);
const currentCheckins=()=>Object.entries(state.checkins).filter(([d])=>d<='2026-10-10');
const checkinCount=()=>currentCheckins().length;
const weekCheckins=()=>currentCheckins().filter(([d])=>d>='2026-10-04').length;
function updateCooldowns(){for(const w of state.wants){const left=Math.max(0,new Date(w.cooldownUntil).getTime()-Date.now());w.hours=Math.ceil(left/3600000);w.status=left>0?'Waiting':'Ready';}}
function communityLogPurchase(record){record.id=newRecordId();record.refund=0;record.currency=state.currency;record.challenge=state.challengeName;record.returnBy=record.returnBy||'';state.purchases.push(record);const p=state.pockets.find(p=>p.name===record.category);if(p)p.spent=Math.round((p.spent+record.amount)*100)/100;}
function renderCommunity(id){const w=want(),o=owned(),p=pocket(),b=purchase();switch(id){
case 'starter':return `${header('A gentle first week')}${title('Start smaller','One category.<br>Seven <em>kind days.</em>','Skip the giant plan. Choose one place to make a little room.')}<div class="card mint-card"><div class="row"><span class="category-icon">${icon('leaf')}</span><div><div class="item-title">Your first week</div><div class="item-sub">Essentials stay welcome. Your history stays.</div></div></div></div>${form('starter',select('My focus','category',['Clothing','Skincare','Home','Books','Tech','Hobbies','Takeaway'],'Clothing')+select('My realistic pace','type',['Low-buy','No-buy'],'Low-buy')+field('My seven-day allowance ('+state.currency+')','budget',25,'number','Only applies to low-buy; choose an amount that fits your circumstances.')+area('One exception I need','exception','Replace something essential that is finished or no longer works for me.')+submit('Review my small start','leaf'))}<p class="footer-note">You can adjust the challenge. A purchase does not send you back to day zero.</p>`;
case 'rule-check':return `${header('Your own rules')}${title('A need deserves context','Replacement?<br>Exception? <em>Let’s notice.</em>','A useful rule leaves room for essentials and things that no longer work for you.')}<div class="card mint-card">${receipt('Thinking about',esc(w.name))}${receipt('Price',money(w.price))}</div>${form('rule-check',select('What is the reason?','reason',['Replacing something finished','Replacing something broken or unsuitable','Health or safety need','A planned gift or occasion','Something new I want'],'Replacing something finished')+select('Does something I own meet this need?','alternative',['No suitable alternative','Yes, something works','I need to check'],'I need to check')+area('The rule or exception this relates to','rule',state.rules[0]||'','Write your own reason. You decide what fits.')+submit('Reflect on this choice'))}<div class="modal-note">You do not need to keep using an unsuitable or unsafe item to meet a challenge.</div>`;
case 'rule-result':{const d=state.ruleDecisions.at(-1)||{reason:'Replacing something finished',alternative:'I need to check',rule:state.rules[0]||'An essential replacement'};return `${header('A thoughtful exception')}${title('Your context matters',d.reason==='Health or safety need'?'Protect the<br><em>essential need.</em>':d.alternative==='Yes, something works'?'There may be<br>another <em>way.</em>':'An exception can<br>be <em>intentional.</em>','This is your reflection, not an automated permission score.')}<div class="card">${receipt('Reason',esc(d.reason))}${receipt('Your alternative',esc(d.alternative))}<div class="stats-divider" style="background:var(--line)"></div><p class="small muted">${esc(d.rule||'No personal rule added.')}</p></div><div class="card mint-card"><p class="small muted">${d.alternative==='Yes, something works'?'Consider using the suitable alternative first. If it no longer meets your need, you can record that context.':'Record the context honestly. Your check-ins and progress are kept, whether you buy or wait.'}</p></div>${action('Log as an allowed exception','exception-purchase','','bag')}${btn('Check what I already own','compare-owned','outline')}${btn('Keep thinking','wishlist','ghost')}`;}
case 'progress-review':return `${header('The progress you keep')}${title('A rhythm, not a reset','Your effort<br>still <em>counts.</em>','A spending day is information. It does not delete all the days before it.')}<div class="card dark-card"><div class="overline">Check-ins in this sample month</div><div class="metric">${checkinCount()}<span style="font-size:20px;opacity:.6"> / 10</span></div>${progress(checkinCount()/10*100)}<p class="subtitle" style="margin-top:13px">${weekCheckins()} of the last 7 demo days. Counted from your check-in records.</p></div><div class="two-col"><div class="card"><div class="overline">Purchases logged</div><div class="metric small">${state.purchases.length}</div><div class="tiny muted">Context preserved</div></div><div class="card mint-card"><div class="overline">Pauses recorded</div><div class="metric small">${state.pauseEvents.length}</div><div class="tiny muted">Your local reflections</div></div></div><div class="section-row"><h2 class="section-title">A record of real life</h2></div>${currentCheckins().slice(-5).reverse().map(([d,c])=>`<div class="list-row"><span class="category-icon ${c.spending==='No purchases'?'':'peach'}">${icon(c.spending==='No purchases'?'leaf':'bag')}</span><div class="grow"><div class="item-title">${esc(d)}</div><div class="item-sub">${esc(c.spending)}${c.sample?' · Sample record':''}</div></div>${icon('check')}</div>`).join('')}<div class="spacer"></div>${btn('One kind next step','recovery','','arrow')}${btn('A smaller challenge','starter','ghost')}`;
case 'joy-menu':{const activities=state.activities.filter(a=>activityEnergy==='All'||a.energy===activityEnergy);return `${header('Life beyond shopping','add-activity','plus')}${title('Your personal alternatives','More joy.<br>Less <em>checkout.</em>','Choose something that fits your energy and uses what you already have.')}${artFrame('ritual','Good things, already here')}<div class="segmented">${['All','Low','Medium','High'].map(v=>`<button class="${activityEnergy===v?'active':''}" data-action="activity-filter" data-value="${v}">${v==='All'?'All energy':v}</button>`).join('')}</div>${activities.map(a=>`<div class="card"><div class="row"><span class="category-icon ${a.energy==='Low'?'peach':''}">${icon(a.energy==='Low'?'cup':'sun')}</span><div class="grow"><div class="item-title">${esc(a.name)}</div><div class="item-sub">${a.minutes} min · ${esc(a.energy)} energy · ${a.done} times enjoyed</div></div></div><div class="spacer" style="height:12px"></div><button class="button outline slim" data-action="enjoy-activity" data-value="${a.id}">I enjoyed this ${icon('check')}</button></div>`).join('')||'<div class="card"><p class="subtitle">No activities for this energy level yet. Add one that feels easy.</p></div>'}${btn('Add my own little joy','add-activity','','plus')}${btn('I’m tempted by food delivery','food-rescue','ghost')}`;}
case 'add-activity':return `${header('A little joy')}${title('Make it personal','Something good<br>you can do <em>now.</em>','No new supplies or purchases required. Keep it easy.')} ${form('activity',field('My activity','name','','text','','Tea with a friend, or a chapter of my book')+select('Energy needed','energy',['Low','Medium','High'],'Low')+field('Minutes, approximately','minutes',10,'number')+submit('Add to my no-spend menu','plus'))}<div class="card mint-card"><p class="small muted">A hobby can become another shopping trigger. Choose an activity you can start with things you already have.</p></div>`;
case 'food-rescue':return `${header('Before food delivery')}${title('An easier default','A little meal.<br>A little <em>less friction.</em>','Start with food you have and an easy meal you already know.')} ${form('pantry',area('What I have at home','ingredients',state.pantryPlan.ingredients,'Only list food that is safe and suitable for you.')+area('My easy meal','meal',state.pantryPlan.meal,'A familiar meal, not a new cooking project.')+area('My low-energy backup','backup',state.pantryPlan.backup,'Something easy for the days you cannot cook.')+submit('Keep this meal plan','check'))}<div class="spacer"></div>${action('I used my food at home','used-food','outline','cup')}${btn('I need groceries or an essential meal','rule-check','ghost')}<p class="footer-note">Food and dietary needs come first. This is a personal plan, not nutrition advice or an automatic recipe generator.</p>`;
case 'friction':return `${header('Change the easy default')}${title('Less debating with yourself','Make shopping<br>less <em>automatic.</em>','Small changes to your environment. You choose what is practical.')}<div class="card">${[['emails','Reduce shopping email','Unsubscribe from a retailer list you do not need.'],['cards','Remove a saved payment method','An optional step in a shopping account you control.'],['apps','Remove a tempting shortcut','Delete a shopping shortcut or mute its notifications.'],['bnpl','Write my no-new-BNPL boundary','Keep existing payment obligations visible.']].map(([k,t,d])=>`<div class="list-row"><div class="grow"><div class="item-title">${t}</div><div class="item-sub">${d}</div></div><button class="switch ${state.friction[k]?'on':''}" role="switch" aria-checked="${state.friction[k]}" aria-label="I completed: ${t}" data-action="friction-step" data-value="${k}"></button></div>`).join('')}</div><div class="card mint-card"><div class="overline">Your completed steps</div><div class="metric small">${Object.values(state.friction).filter(Boolean).length} / 4</div><p class="small muted">This is your manual checklist. It cannot block apps, remove cards or unsubscribe for you.</p></div>${btn('My payment commitments','commitments','outline')}${btn('Choose something else to do','joy-menu','ghost')}`;
case 'use-up':return `${header('Your enough collection','add-owned','plus')}${title('Use the good things here','Open it.<br>Enjoy it. <em>Finish it.</em>','Keep one small use-up plan. There is no need to use anything unsafe or unsuitable.')}${illustratedNote('Your enough collection','Good things.<br>Already yours.','wardrobe','owned')} ${state.owned.map(item=>`<button class="card" data-action="open-use-up" data-value="${item.id}" style="text-align:left;width:100%;color:var(--forest)"><div class="row"><span class="wish-art green">${icon(item.icon)}</span><div class="grow"><div class="item-title">${esc(item.name)}</div><div class="item-sub">${esc(item.useStatus)} · ${item.remaining}% remaining</div></div>${icon('chevron')}</div><div class="spacer" style="height:12px"></div>${progress(item.remaining)}</button>`).join('')}<div class="spacer"></div>${btn('Make room, one item at a time','declutter','outline')}`;
case 'use-up-item':return `${header('Use-up progress')}<div class="item-hero">${icon(o.icon)}</div>${title('Already yours',esc(o.name),'An estimate is enough. No need to measure every use.')} ${form('use-up',field('Remaining amount, approximately (%)','remaining',o.remaining,'number','For books/projects, estimate the portion still to enjoy or complete.')+select('How is this item doing?','status',['In use','Finished','Needs repair','Unsuitable or unsafe','Given away'],o.useStatus)+submit('Save my progress','check'))}<div class="spacer"></div>${btn('Is a replacement needed?','rule-check','outline')}<p class="footer-note">Do not use an expired, unsuitable or unsafe item just to finish it.</p>`;
case 'declutter':return `${header('A little less overwhelm')}${title('One item is enough','A small space.<br>Not a whole <em>house.</em>','Pick one thing. Give it a sensible next step.')} ${form('declutter',select('The item','item',state.owned.map(x=>x.name),o.name)+select('My next step','step',['Keep and use','Repair before replacing','Give away responsibly','Consider selling','Dispose responsibly'],'Keep and use')+area('My practical plan (optional)','note','','No pressure to buy organizing supplies.')+submit('Keep this small plan','leaf'))}<div class="section-row"><h2 class="section-title">Your small steps</h2><span class="chip">${state.declutterLog.length}</span></div>${state.declutterLog.slice(-3).reverse().map(x=>`<div class="card"><div class="item-title">${esc(x.name)}</div><p class="small muted">${esc(x.step)}</p></div>`).join('')||'<p class="subtitle">One little decision can be the start.</p>'}`;
case 'deal-check':return `${header('A deal or a need?')}${title('Before the discount decides','It still costs<br><em>real money.</em>','A lower price does not create a need. Start with what you planned to buy.')} ${form('deal',field('The item','name',draft.deal?.name||'')+field('Price I would actually pay ('+state.currency+')','price',draft.deal?.price||'','number')+field('Retailer’s comparison price (optional)','anchor',draft.deal?.anchor||'','number','Entered by you. This app does not verify retailer price history.')+select('Did I want or need it before seeing the deal?','planned',['No','Yes','Not sure'],draft.deal?.planned||'No')+submit('See the real decision','arrow'))}<div id="deal-result">${draft.deal?renderDealResult():''}</div>`;
case 'pockets':return `${header('Your allowance pockets')}${title('Room for a real life','A little fun.<br>A clear <em>boundary.</em>','Personal category budgets, separate from your overall challenge.')} ${state.pockets.map(x=>`<button class="card" data-action="open-pocket" data-value="${x.id}" style="text-align:left;width:100%;color:var(--forest)"><div class="row between"><h2 class="section-title">${esc(x.name)}</h2><span class="chip">${x.rollover?'Carry-over on':'This period only'}</span></div><div class="metric">${money(pocketAvailable(x))}<span class="tiny muted" style="font-family:Arial;letter-spacing:0"> left</span></div>${progress((x.limit+(x.rollover?x.carry:0))?x.spent/(x.limit+(x.rollover?x.carry:0))*100:0)}<div class="row between tiny muted" style="margin-top:12px"><span>${money(x.spent)} logged · ${money(x.limit)} allowance</span><span>${x.rollover?money(x.carry)+' carried in':''}</span></div></button>`).join('')}<div class="card mint-card"><p class="small muted">Carry-in is manually entered from a previous period. It is not bank savings, and never increases money set aside.</p></div>${action('Create a pocket','new-pocket','outline','plus')}`;
case 'edit-pocket':return `${header('A personal allowance')}${title('A realistic boundary','Enough room<br>to <em>keep going.</em>','Name a category exactly as in your purchase logs to keep the totals connected.')} ${form('pocket',field('Category name','name',draft.newPocket?'':p.name)+field('Allowance for this period ('+state.currency+')','limit',draft.newPocket?'':p.limit,'number')+select('Carry unused allowance from the previous period?','rollover',['No','Yes'],!draft.newPocket&&p.rollover?'Yes':'No')+field('Unused amount carried in ('+state.currency+')','carry',draft.newPocket?0:p.carry,'number','Only applied when carry-over is on. Enter your own prior-period amount.')+submit('Save my pocket','check'))}`;
case 'subscriptions':{const active=state.subscriptions.filter(s=>s.status==='Active');const total=active.reduce((n,s)=>n+s.amount,0);return `${header('Recurring spending','add-subscription','plus')}${title('Keep what earns its place','What do you<br><em>actually use?</em>','A small review of recurring costs. No need to cancel something that helps you.')}<div class="card dark-card"><div class="overline">Listed active monthly costs</div><div class="metric">${money(total)}</div><div class="subtitle">${money(total*12)} per year if unchanged · Projection, not savings.</div></div>${state.subscriptions.map(s=>`<div class="card"><div class="row between"><div><div class="item-title">${esc(s.name)}</div><div class="item-sub">${money(s.amount)}/month · ${s.used?'Useful to me':'Not using'} · ${s.status}</div></div>${icon(s.status==='Cancelled'?'check':'calendar')}</div>${s.status==='Active'?`<div class="spacer" style="height:12px"></div><button class="button outline slim" data-action="cancel-subscription" data-value="${s.id}">${draft.cancelSubscription===s.id?'Confirm: I already cancelled it':'I cancelled this myself'}</button>`:''}</div>`).join('')}<p class="footer-note">Cancellation is your own action with the provider. This app records your confirmation and makes no cancellation request.</p>`;}
case 'add-subscription':return `${header('A recurring cost')}${form('subscription',field('Subscription or recurring service','name')+field('Monthly cost ('+state.currency+')','amount','','number')+select('Is it useful to me right now?','used',['Yes','No'],'No')+submit('Add to my review','plus'))}`;
case 'purchase-history':return `${header('Your purchase history','purchase-log','plus')}${title('Keep the context','Real spending.<br>Real <em>life.</em>','Planned purchases and exceptions belong here, too.')} ${state.purchases.map(x=>`<button class="card choice" data-action="open-purchase" data-value="${x.id}"><span class="category-icon peach">${icon(x.refund?'reset':'bag')}</span><span class="grow"><span class="item-title">${esc(x.name)}</span><span class="item-sub" style="display:block">${esc(x.kind)} · ${esc(x.category)}${x.refund?' · Refund recorded':''}</span></span><strong class="small">${money(x.amount-x.refund)}</strong>${icon('chevron')}</button>`).join('')||`<div class="center empty-art">${art('garden','small')}<p class="subtitle">No purchases logged yet. You don’t need to add one to show progress.</p></div>`}<div class="spacer"></div>${btn('Log a purchase honestly','purchase-log','','plus')}${btn('See the progress I keep','progress-review','ghost')}`;
case 'return-check':return `${header('A purchase with context')}${title('If a return makes sense',esc(b?.name||'Your purchase'),'Your own policy, your own decision. Never a promised refund.')} ${b?`<div class="card">${receipt('Paid',money(b.amount))}${receipt('Context',esc(b.kind))}${receipt('Refund confirmed',money(b.refund||0))}</div>${form('return',field('Return-by date from the retailer (optional)','date',b.returnBy||'','date','Enter the actual policy date from your receipt; rules differ by retailer.')+field('Additional amount already refunded ('+state.currency+')','amount','','number','Leave blank to save the date. Only enter money already returned to you.')+submit('Save my return record','check'))}<div class="card mint-card"><p class="small muted">A confirmed refund reduces net logged spending for this purchase. It never becomes skipped spending or money set aside automatically.</p></div>`:'<div class="card"><p class="subtitle">Log a purchase first to track its context or a confirmed refund.</p></div>'+btn('Log a purchase','purchase-log')}<div class="spacer"></div>${btn('A kind next step','recovery','ghost')}`;
case 'commitments':return `${header('Payment commitments')}${title('Keep obligations visible','A little<br><em>more clarity.</em>','Manual records for existing payments. No accounts connected, no repayment strategy prescribed.')} ${state.commitments.map(c=>`<div class="card"><div class="row between"><div class="item-title">${esc(c.name)}</div><span class="chip">${esc(c.type)}</span></div><div class="metric small">${money(c.balance)}<span class="tiny muted" style="font-family:Arial;letter-spacing:0"> remaining</span></div>${receipt('My planned payment',money(c.payment))}${receipt('My due date',esc(c.due))}<button class="button outline slim" data-action="open-commitment" data-value="${c.id}">Update this commitment ${icon('edit')}</button></div>`).join('')||'<div class="card mint-card"><p class="quote">A clear record is a useful first step.</p><p class="small muted" style="margin-top:12px">Add an existing balance and the payment you have planned. This tool does not calculate interest or recommend borrowing.</p></div>'}${action('Add a payment commitment','new-commitment','','plus')}${btn('My no-new-BNPL boundary','friction','ghost')}`;
case 'add-commitment':{const c=state.commitments.find(x=>x.id===selectedCommitment);return `${header(c?'Update a commitment':'A payment commitment')}${form('commitment',field('Name','name',c?.name||'')+select('Type','type',['BNPL','Credit card','Loan','Other'],c?.type||'BNPL')+field('Current remaining balance ('+state.currency+')','balance',c?.balance??'','number','Enter your own current balance; no interest or fees are calculated.')+field('My planned payment ('+state.currency+')','payment',c?.payment??'','number')+field('Next due date','due',c?.due||'','date')+submit('Save this commitment','check'))}<p class="footer-note">Dates are stored locally. Scheduled notifications and payment services are not connected.</p>`;}
default:return null;}}
function renderDealResult(){const d=draft.deal;return `<div class="card dark-card" style="margin-top:20px"><div class="overline">The real outflow</div><div class="metric">${money(d.price)}</div><p class="subtitle">${d.planned==='Yes'?'You wanted it before the offer. Now check your rules, alternatives and allowance.':'The deal introduced the want. You can let the offer pass without losing money you planned to keep.'}</p></div>${action('Let the thought wait','deal-wait','','clock')}${btn('Check my own rules','rule-check','ghost')}`;}
function handleCommunityAction(name,value,el){switch(name){
case 'activity-filter':activityEnergy=value;render();return true;
case 'enjoy-activity':{const a=state.activities.find(a=>a.id===Number(value));if(a){a.done++;state.reflections.push('Enjoyed: '+a.name);persist();render();toast('A little joy, without a checkout.');}return true;}
case 'used-food':state.reflections.push('Used food at home: '+state.pantryPlan.meal);persist();toast('Meal noted. No money has been counted as savings.');return true;
case 'friction-step':state.friction[value]=!state.friction[value];persist();render();return true;
case 'open-use-up':selectedOwned=Number(value);go('use-up-item');return true;
case 'open-pocket':selectedPocket=Number(value);draft.newPocket=false;go('edit-pocket');return true;
case 'new-pocket':draft.newPocket=true;go('edit-pocket');return true;
case 'cancel-subscription':{const s=state.subscriptions.find(s=>s.id===Number(value));if(!s)return true;if(draft.cancelSubscription!==s.id){draft.cancelSubscription=s.id;render();toast('Confirm only after you cancelled with the provider.');return true;}s.status='Cancelled';draft.cancelSubscription=null;persist();render();toast('Your manual cancellation confirmation is recorded.');return true;}
case 'open-purchase':selectedPurchase=Number(value);go('return-check');return true;
case 'open-commitment':selectedCommitment=Number(value);go('add-commitment');return true;
case 'new-commitment':selectedCommitment=0;go('add-commitment');return true;
case 'exception-purchase':draft.exceptionPurchase=true;go('purchase-log');return true;
case 'deal-wait':draft.newWantName=draft.deal.name;draft.newWantPrice=draft.deal.price;go('add-item');return true;
default:return false;}}
function handleCommunityForm(id,data,error,required,positive){switch(id){
case 'starter':if(!positive('budget','allowance',true)||!required('exception','An exception'))return true;state.challengeType=data.type;state.categories=[data.category];state.challengeName='My small seven-day start';state.budget=Number(data.budget);state.rules=[data.exception];draft.duration='7 days';persist();go('challenge-review');return true;
case 'rule-check':state.ruleDecisions.push({...data,date:new Date().toISOString()});persist();go('rule-result');return true;
case 'activity':if(!required('name','An activity')||!positive('minutes','number of minutes'))return true;state.activities.push({id:newRecordId(),name:data.name.trim(),energy:data.energy,minutes:Math.max(1,Math.round(Number(data.minutes))),done:0});persist();go('joy-menu');return true;
case 'pantry':if(!required('meal','An easy meal'))return true;state.pantryPlan=data;persist();toast('Your easy meal and backup are saved.');return true;
case 'use-up':if(!positive('remaining','remaining percentage',true))return true;if(Number(data.remaining)>100){error('Use a percentage from 0 to 100.','remaining');return true;}owned().remaining=data.status==='Finished'?0:Number(data.remaining);owned().useStatus=data.status;persist();go('use-up');toast('Your use-up estimate is saved.');return true;
case 'declutter':state.declutterLog.push({name:data.item,step:data.step,note:data.note,date:new Date().toISOString()});if(data.step==='Keep and use'){const o=state.owned.find(x=>x.name===data.item);if(o)o.useStatus='In use';}persist();render();toast('One small step recorded.');return true;
case 'deal':if(!required('name','An item name')||!positive('price','price'))return true;if(data.anchor!==''&&!positive('anchor','comparison price',true))return true;draft.deal={...data,price:Number(data.price),anchor:Number(data.anchor)||0};render();document.getElementById('deal-result')?.scrollIntoView({behavior:'smooth',block:'end'});return true;
case 'pocket':if(!required('name','A category')||!positive('limit','allowance',true)||!positive('carry','carry-in amount',true))return true;{const existing=state.pockets.find(p=>p.name.toLowerCase()===data.name.trim().toLowerCase()&&(draft.newPocket||p.id!==selectedPocket));if(existing){error('This category already has a pocket. Edit that one instead.','name');return true;}const values={name:data.name.trim(),limit:Number(data.limit),carry:Number(data.carry),rollover:data.rollover==='Yes'};if(draft.newPocket){state.pockets.push({id:newRecordId(),spent:state.purchases.filter(p=>p.category===values.name).reduce((n,p)=>n+p.amount-(p.refund||0),0),...values})}else Object.assign(pocket(),values);draft.newPocket=false;persist();go('pockets');toast('Your pocket is saved. Carry-in is not cash savings.');return true;}
case 'subscription':if(!required('name','A service name')||!positive('amount','monthly amount',true))return true;state.subscriptions.push({id:newRecordId(),name:data.name.trim(),amount:Number(data.amount),used:data.used==='Yes',status:'Active'});persist();go('subscriptions');return true;
case 'return':{const p=purchase();if(!p)return true;const amount=data.amount===''?0:Number(data.amount);if(!Number.isFinite(amount)||amount<0||amount>p.amount-(p.refund||0)){error('Enter an additional confirmed refund no greater than the remaining purchase cost.','amount');return true;}p.returnBy=data.date;p.refund=Math.round(((p.refund||0)+amount)*100)/100;state.refundTotal=Math.round((state.refundTotal+amount)*100)/100;if(p.challenge===state.challengeName&&state.categories.includes(p.category))state.spent=Math.max(0,Math.round((state.spent-amount)*100)/100);const pk=state.pockets.find(x=>x.name===p.category);if(pk)pk.spent=Math.max(0,Math.round((pk.spent-amount)*100)/100);persist();go('purchase-history');toast(amount?'Confirmed refund recorded. Savings totals stay separate.':'Return policy date saved. No return has been initiated.');return true;}
case 'commitment':if(!required('name','A name')||!positive('balance','remaining balance',true)||!positive('payment','planned payment',true)||!required('due','A due date'))return true;{const values={name:data.name.trim(),type:data.type,balance:Number(data.balance),payment:Number(data.payment),due:data.due};const c=state.commitments.find(x=>x.id===selectedCommitment);if(c)Object.assign(c,values);else state.commitments.push({id:newRecordId(),...values});persist();go('commitments');toast('Your manual payment record is saved.');return true;}
default:return false;}}
